INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '9f347a18-97bc-5f2e-92ba-4f058dd5896e', '53ad4363-4311-591f-8c8f-8d4c1c2f9014',
  'Given a string $S$ of characters, a *duplicate removal* consists of choosing two adjacent and equal letters, and removing them.

We repeatedly make duplicate removals on $S$ until we no longer can.

Return the final string after all such duplicate removals have been made.

**For example:**

| Test | Result |
| :--- | :--- |
| `cout << removeDuplicates("abbaca");` | `ca` |
| `cout << removeDuplicates("aab");` | `b` |

Đáp án: ```cpp
string removeDuplicates(string S){
    stack <char> st;
    int size = S.size();
    for (int i = 0; i < size; ++i){
        if (i == 0) {
            st.push(S[i]);
            continue;
        }
        if (st.empty() != true && S[i] == st.top()) {
            st.pop();
        }
        else st.push(S[i]);
    }
    string res = "";
    while (!st.empty()){
        res.push_back(st.top());
        st.pop();
    }
    string res1 = "";
    size = (int)res.size();
    for (int i = size - 1; i >= 0 ; --i){
        res1.push_back(res[i]);
    }
    return res1;
}
```', 5
);

